def variants(shape):
    out=set()
    for k in range(4):
        pts=shape
        for _ in range(k): pts={(c,-r) for r,c in pts}
        for mirror in (False,True):
            q={(r,-c if mirror else c) for r,c in pts}
            mr=min(r for r,c in q); mc=min(c for r,c in q)
            out.add(frozenset((r-mr,c-mc) for r,c in q))
    return out
def transform_occ(a, color):
    h,w=len(a),len(a[0]); seed={(r,c) for r,row in enumerate(a) for c,x in enumerate(row) if x==color}
    marked=set()
    for sh in variants(seed):
      hh=max(r for r,c in sh)+1; ww=max(c for r,c in sh)+1
      for i in range(h-hh+1):
       for j in range(w-ww+1):
        cells={(i+r,j+c) for r,c in sh}
        if all(a[r][c]==0 for r,c in cells): marked |= cells
    return marked
